#!/usr/bin/env python3
"""VLM prompt templates for navigation system."""

from typing import Dict, Any


class VLMPrompts:
    """Collection of VLM prompt templates."""

    @staticmethod
    def web_search_prompt(goal: str) -> str:
        """Prompt to decide if web search is needed for goal."""
        return f"""Decide whether you need to search the internet to find where this is: {goal}.
Return yes only if you are told to go to someone's office and need to look up that person's office number.
If yes, return search keywords (separated by spaces) in the form: Yes; keywords
If no, return: No; No keywords"""

    @staticmethod
    def describe_scene_prompt() -> str:
        """Prompt to describe current scene from image."""
        return "Describe the scene in the image? Use mostly keywords and less than 10 words"

    @staticmethod
    def web_search_decision_prompt(goal: str) -> str:
        """Prompt to decide whether web search is needed."""
        return f"""Decide whether you need to search the internet to find where this is: {goal}.
Return yes only if you are told to go to someone's office and need to look up that person's office number.
If yes, return search keywords (separated by spaces) in the form: Yes; keywords
If no, return: No; No keywords"""

    @staticmethod
    def read_door_number_prompt() -> str:
        """Prompt to read door number from image."""
        return """What is the door number in the image? Return only the number and confidence score (to 2 decimal places), separated by a semicolon.
Reproduce the label exactly as printed, including any letter prefix: room numbers here are a letter followed by digits (the prefix is T), and dropping the letter makes the answer useless. Transcribe only digits you can actually make out -- never fill in a plausible number.
The image is often dark and noisy: the plate is a small dark oval with light text. Read it anyway if the digits are distinguishable, and reserve -1/-2 for when they truly are not.
If you can't see a sign or you can only read half of the sign, return -1; confidence score.
If you can see the sign but you can't read the numbers, return -2; confidence score.
Your confidence score should be between 0 and 1. Be more conservative with your estimates."""

    @staticmethod
    def sign_entries_prompt() -> str:
        """Read a directional sign into label ranges and their arrows.

        Only the reading is asked of the model. Turning an arrow into a map
        direction is done in code from where the photo was taken; asked to do
        that itself the model kept mapping "left" to the map's west edge.
        """
        # No example label in the format line: with a sign too small to read,
        # the model copied the example ("T131-T150") verbatim and the run then
        # followed a range that was never on the sign.
        return """Image 1 is a close-up of a directional sign; image 2 is the whole camera frame it was cut from. List every label printed on the sign together with the arrow that belongs to it.
Answer with JSON only, no prose: a list of objects with two keys, "label" and "arrow".
- "label": the text exactly as printed, keeping any letter prefix (the letter before the digits is part of the label). Write a range as LOW-HIGH.
- "arrow": one of "left", "right", "up", "down"; "none" if that label has no arrow.
Only transcribe characters you can actually make out. If the sign is too small or blurred to read its digits with certainty, or there is no directional sign in the photo, answer [] -- never guess a number and never fill in a plausible-looking range."""
    @staticmethod
    def read_sign_directions_prompt() -> str:
        """Prompt to read directional sign from image."""
        return """Break down the directional sign you see in the image.
Return your answer in the form {'left': [content], 'right': [content], 'forward': [content], 'backwards': [content]}. Return only the dict (no comments or formatting)."""

    @staticmethod
    def convert_sign_directions_prompt(sign_dict: Dict[str, Any]) -> str:
        """Prompt to convert relative sign directions to absolute map directions."""
        return f"""
You are given a 2D occupancy grid map generated by ROS. The map includes:
- 🤖: The robot's position at the moment it sees the sign 🧭.
- 🧭: The location of the signpost.
- The map does not contain an arrow indicating the robot's viewing direction. You must infer the robot's facing direction by comparing the relative positions of 🤖 and 🧭.
Additionally, you are provided a sign dictionary in relative directions to the robot (left, right, forward, backwards).
**Your task is:**
Convert the relative direction sign dictionary into an absolute map direction (**North, South, East, or West**) based on the robot's inferred orientation, and categorize the area names by direction.

Return the result as a Python dictionary in the following format:
{{
"North": […area names…],
"South": […area names…],
"East": […area names…],
"West": […area names…]
}}

Only return this dictionary. Do not explain your reasoning, and do not include any extra text.

Relative sign dictionary:
{sign_dict}
"""

    @staticmethod
    def choose_next_landmark_prompt(target: str, keypoints_dict: Dict[str, Any],
                                    sign_lines=None, corridor_lines=None) -> str:
        """Prompt for VLM to choose next navigation landmark.

        sign_lines describes the directional-sign photos attached after the map
        (see VLMNav._sign_context). Distilling an arrow down to a cardinal
        string throws away the one thing that makes it readable -- what the
        arrow points *at* -- so the photos are passed through instead and the
        reasoning about them happens here.
        """
        rooms_read = sum(1 for v in keypoints_dict.values()
                         if isinstance(v, dict) and v.get('room'))
        doors_unvisited = sum(1 for v in keypoints_dict.values()
                              if isinstance(v, dict) and 'Unvisited_door' in str(v.get('name', '')))
        pattern_block = f"""

Doors before frontiers. You have read {rooms_read} room number(s) so far. A
frontier only reveals more corridor; a door plate tells you where the target
is. Whenever an Unvisited_door is within reach (roughly 8 m) and no sign says
that side is wrong, go and read it before choosing any frontier. Room numbers
are read automatically as you pass within about 3 m of a plate. If a sign
covers the target, it still fixes the DIRECTION -- but on that side, prefer a
door over a frontier."""

        sign_block = ""
        if sign_lines:
            sign_block = """

Attached after the map are photographs of directional signs you have already
passed. For each one you are told which map icon it is, where it stands, where
you stood when the photo was taken, and what a separate close-up pass read on it:

""" + "\n".join(sign_lines) + """

Some photo lines also say what the sign reads ("It reads: 'T131-T150' with a
left arrow"), from a separate close-up pass; if that disagrees with what you see
in the photo, trust the photo. Then reason like this, in order:
  1. Does any range on a sign contain the target number? If yes, that sign
     decides -- you must not leave its range, and you must not pick a landmark
     that is not in the list for its arrow.
  2. Take the arrow's list (LEFT list for a left arrow, RIGHT for right). The
     FIRST entry is the opening the arrow means. Go through it, then WALK THAT
     CORRIDOR the way a person would: read the nearest unvisited door AHEAD of
     you, then the next one ahead, on either side of the corridor, in order of
     distance ahead -- until the numbers you have read (both sides; they are
     separate runs) tell you which side and which direction the target is, then
     go straight to it. Take the frontier at the far end of that corridor only
     when no unvisited door ahead of you is left in it. The list holds only
     places still worth going to: doors already read there are given in brackets
     as numbers, for reasoning about the run, never as destinations. Nothing in
     that list is behind you; nothing behind you is ever the answer, and
     "nearest" never means turning round.
     Example: sign 'T131-T150' left arrow, you are in that corridor, T132 read
     on the left and T146 read on the right, target T142: the 140s are on the
     RIGHT side, so read the next unvisited door ahead on the right; if it reads
     T148 you are walking up the run and T142 is behind T146 -- only then turn.
  3. A sign whose ranges do NOT contain the target does not point the way.
     Never follow its arrow "to keep progressing" -- it tells you where OTHER
     rooms are, so the opening it points to is the LESS likely one. Only when
     no sign covers the target do doors, frontiers and distance decide, and
     then prefer openings a non-matching sign does not point at.
Do NOT work out a map direction from any angle -- the geometry is already done
for you from where the photo was taken. Each photo line sorts the landmarks ahead of that
person into LEFT of the sign and RIGHT of the sign, each with how far to the
side and how far ahead it lies. A left arrow means: choose from the LEFT list.
The opening a wall sign points at is usually RIGHT BESIDE it -- a corridor mouth
a few decimetres to the side that then runs metres ahead -- so prefer the entry
marked "right beside the sign" with a long "ahead" over one far off to the
side. A right arrow: the RIGHT list. An up arrow: whichever entry is closest to
straight ahead and farthest ahead.

The map's left and right EDGES are compass W and E. They have nothing to do
with an arrow's left and right, which are relative to the person facing the
sign -- that person may be facing any compass direction. Never translate an
arrow into "west" or "east"; take the landmark named in its list. The FIRST
entry of the LEFT list is the opening a left arrow on that sign means, and the
first entry of the RIGHT list the opening a right arrow means. If the arrow's
list is empty ("nothing left to visit there"), everything on that side is
already visited or behind you: the sign has nothing more to say -- do NOT go
back towards it; follow the corridor block instead.

An arrow is a hint about **which opening to take**, not a heading to turn to.
A left arrow beside a corridor mouth that recedes away from the camera means
"go through that opening", not "turn ninety degrees left" -- the opening may
sit only twenty or thirty degrees off straight ahead. Match the arrow against
the free space on the map and pick the opening, frontier or door that lies
along it. If several openings are consistent with the arrow, the sign cannot
settle it on its own: choose the one that gets you closest to reading another
sign or door number, and resolve it there."""

        corridor_block = ""
        if corridor_lines:
            corridor_block = """

YOUR CORRIDOR -- worked out from the path you actually walked, not from any
sign. "Ahead" and "behind" here mean along your direction of travel, from where
you stand now; "left"/"right" are the two sides of that corridor:

""" + "\n".join(corridor_lines) + """

Walk it like a person: keep going FORWARD, reading the next unvisited door
AHEAD on either side, until the numbers say the target is behind you -- only
then turn round. The two sides carry separate runs; the side whose numbers are
nearest the target is the side to read. If the block says the target should be
N m AHEAD, go to the unvisited door nearest that spot, or to the frontier ahead
if no door is mapped there yet. Choosing anything from the BEHIND list while the
AHEAD list is not empty is wrong unless the numbers put the target behind you."""

        return f"""
You are a robot 🤖 trying to find {target}.
The map depicts the environment you've explored so far with doors (🚪), signs (🧭), people (😊), and frontiers (⭐). The borders are labelled N, S, E and W. These name the map's own axes and are stable for the whole run; use them to say which way to go.
The JSON provided below maps each landmark index on the map to its name, the room number if one has been read off it, and info from people. It deliberately carries NOTHING about what the signs say: a sign's meaning is in the photograph of it, attached after the map, and you are to read the arrow there yourself. Never conclude you have no directional information because the JSON has none -- look at the sign photos.

Choose the next landmark to go to based on the provided map and JSON.
Reason over how to most **efficiently** find the target, like going to directions signs to narrow down regions, following ascending/descending door number patterns, visiting nearest doors to see their room number, asking a person nearby for directions, or exploring frontiers to find more landmarks.

Landmark names are "Visited_<class>_<i>" or "Unvisited_<class>_<i>", where i is
just an identifier -- it is NOT a room number, and it says NOTHING about where
the landmark is: index 7 is not "between" 6 and 8. Every landmark carries
'from_you' = its distance and direction relative to where you are facing now
("12 m ahead", "3 m behind-left"); that, and the map, are what position means.
"Continue along the corridor" means picking something AHEAD, never something
tens of metres behind you. A door whose number was actually
read carries it in a separate 'room' field; a door with no 'room' field is one
whose number is still unknown, so infer nothing about its number from its name.
Use the 'room' values to identify door numbering patterns, and follow those
patterns efficiently: in an ascending run, if you are at room 100 and looking
for room 110, skip 101, 102, and so on. The two sides of a corridor usually
carry SEPARATE runs (e.g. 130s on one side, 140s on the other), so if every
number you have read is from doors on one side and the target is not in that
run, read a door on the OTHER side (use 'from_you': left vs right) before
concluding the target is not in this corridor. Room numbers may carry a letter prefix
(T106); compare them as written.

Keep in mind that all information from signs, people, etc. are relative to the position of that particular landmark, and is probably only applicable in a local region of that landmark.

If an unvisited person is nearby and you want to ask for more information on where to go, choose the person.
Information provided by a visited person will be listed in 'info' using cardinal directions. Use this information.
Example:
    Input: target='Room 3339', info="I should go North to find the door"
    Output: You will pick a landmark to the north of the image.

A room range on a sign tells you which side of the building the target is on, and
takes precedence over simply heading for whatever is nearest. Check whether the
target falls inside the range before following the arrow: if you are already
inside it, the arrow means "keep going along this corridor" rather than "leave
for somewhere else".
Example:
    Input: target='Room 3339', a sign photo reads 'Room 3326-3340' with an arrow
    Output: 3339 is inside 3326-3340, so you follow that arrow and pick the
            opening it points to.

**Do not choose landmarks that are already visited (i.e. names that look like "Visited_obj_id"**.

{pattern_block}{sign_block}{corridor_block}

First, think carefully step by step about where the target room might be and decide which landmarks to visit next. Then, print out your reasoning followed by the chosen landmark indices in brackets, IN THE ORDER TO VISIT THEM -- up to three. The first is where to go now; the rest are the plan after it. A door you will walk past on the way costs only the detour to stand in front of it (its plate is read as you pass), so list such doors first and end with the opening or frontier to continue through. The plan is dropped and you are asked again the moment something changes (a sign read, a goal unreachable), so do not hedge -- commit to the best sequence.
Example: I am looking for Room 110. The sign in photo 1 reads '100-120' with an arrow, and its LEFT list names door 3, door 5 and frontier 1 down that corridor. Doors 3 and 5 are on the way and their plates will tell me how the numbers run, then frontier 1 continues the corridor; Chosen landmarks: [3], [5], [1]
JSON:
{keypoints_dict}
"""